scenario.en:
async function* gen() {
  try {
    console.log('A');
    yield 1;
    console.log('B');
    yield 2;
    console.log('C');
  } finally {
    console.log('cleanup');
  }
}

for await (const n of gen()) {
  console.log('got', n);
  if (n === 1) break;
}

What is logged, in order? Does 'B', 'C', or 'cleanup' appear?

